CREATE TRIGGER IF NOT EXISTS receiving_bfb64f92_ledger_after_insert AFTER INSERT ON receiving_bfb64f92_shipments BEGIN
  INSERT INTO receiving_bfb64f92_ledger (supplier, shipment_count, total_value) VALUES (NEW.supplier, 1, NEW.value)
  ON CONFLICT(supplier) DO UPDATE SET shipment_count = shipment_count + 1, total_value = total_value + NEW.value;
END;
CREATE TRIGGER IF NOT EXISTS receiving_bfb64f92_ledger_after_update AFTER UPDATE OF value ON receiving_bfb64f92_shipments BEGIN
  UPDATE receiving_bfb64f92_ledger SET total_value = total_value + (NEW.value - OLD.value) WHERE supplier = NEW.supplier;
END;

